messages.content:
{
  "overview": {
    "text": "Indian Overseas Bank invites IRDAI-licensed Stand-Alone Health Insurance companies for a corporate agency tie-up to distribute health insurance products to its customers through branches and digital channels. The arrangement is initially for 3 years, renewable at the Bank's discretion for a further 3 years. Reference RFP/SAHI/003/2026-27, dated 11.05.2026.",
    "pages": [
      1,
      7
    ]
  }
}

{
  "issuing_organization": "Indian Overseas Bank; Marketing & Development Department, 763 Anna Salai, Central Office, Chennai-600002; Ref. RFP/SAHI/003/2026-27; queries: mdd@iob.bank.in, 044-28519639/ 044-71729204",
  "issuing_organization_pages": [
    1,
    4
  ]
}

{
  "scope": [
    {
      "text": "Corporate agency arrangement with one or more additional Stand-Alone Health Insurance companies to distribute individual and group health insurance products through branches and digital channels including internet banking and mobile banking.",
      "pages": [
        7
      ]
    },
    {
      "text": "Customise insurance products for every segment of the Bank's customers, with premiums in tune with market rates and competitive.",
      "pages": [
        7
      ]
    },
    {
      "text": "Support the Bank on sales, renewals, claims, customer complaint resolution, MIS, training, IT and manpower across the country.",
      "pages": [
        8
      ]
    },
    {
      "text": "Provide day-to-day data on policies issued, renewals, lapses and claims, with real-time data exchange with the Bank, and give the Bank portal access through a User ID and password.",
      "pages": [
        8
      ]
    },
    {
      "text": "Source business from all centres for the initial 01 year; permission for the subsequent 2 years may be extended by the Bank on satisfactory performance, subject to annual review.",
      "pages": [
        8
      ]
    },
    {
      "text": "Provide MIS updates on status of customer complaints on a weekly/fortnightly/monthly basis.",
      "pages": [
        8
      ]
    },
    {
      "text": "Settle claims without delay and within IRDAI timelines, run a grievance redressal procedure, issue renewal notices well before expiry, and issue policy documents and endorsements without delay.",
      "pages": [
        9
      ]
    },
    {
      "text": "Annexure 16 information security scope applies if data is hosted on the successful bidder's own premises (data centre).",
      "pages": [
        40
      ]
    }
  ]
}

{
  "key_requirements": [
    {
      "text": "Bid must meet every minimum eligibility criterion in Annexure-1; a proposal failing any one is rejected straight away.",
      "pages": [
        10
      ]
    },
    {
      "text": "Bidder must sign the Pre-Contract Integrity Pact (Annexure-17); a bidder not signing or refusing to sign is disqualified.",
      "pages": [
        19
      ]
    },
    {
      "text": "Bid must be submitted only through the Bank's e-tendering portal using a Class III Digital Certificate with signing and encryption; email, fax, post or courier bids are rejected.",
      "pages": [
        4,
        13
      ]
    },
    {
      "text": "Successful bidder must not sub-contract any part of the services without the Bank's prior written consent.",
      "pages": [
        9
      ]
    },
    {
      "text": "Successful bidder must inform the Bank within 24 hours of any regulatory breach, penalty, show cause or warning issued by IRDAI, SEBI, RBI or other regulators.",
      "pages": [
        9
      ]
    },
    {
      "text": "Successful bidder must bear all expenditure on integration of APIs, technology or system synchronisation, and comply with all applicable IRDAI regulations and guidelines.",
      "pages": [
        9
      ]
    },
    {
      "text": "Successful bidder must keep Bank customer data confidential and not use or disclose it for any purpose other than services under this RFP and the Agreement.",
      "pages": [
        9
      ]
    },
    {
      "text": "Successful bidder must provide online system access for MIS and MIS reports on business under the contract, and maintain policyholder records in safe custody.",
      "pages": [
        19
      ]
    }
  ]
}

{
  "key_requirements": [
    {
      "text": "AI/ML models used by the bidder must not be trained on Bank or Bank customer sensitive data and must be deployed on-premises by default; cloud or third-party AI needs the Bank's prior approval.",
      "pages": [
        40
      ]
    },
    {
      "text": "Bank must be notified within 4 hours of any suspected data breach from discovery; vulnerability assessment at least half-yearly and penetration testing at least yearly.",
      "pages": [
        42,
        44
      ]
    }
  ]
}

{
  "eligibility": [
    {
      "text": "Must hold a valid IRDAI insurance licence, valid on the date of RFP submission; copy of original licence and current licence with proof of renewal required.",
      "pages": [
        10
      ]
    },
    {
      "text": "Must be a government organization/PSU or a company registered under the Companies Act 1956 /2013 and with IRDAI, in existence for at least 5 years in standalone health insurance with business in India in the last 5 years.",
      "pages": [
        10
      ]
    },
    {
      "text": "Must have at least 3 years of experience in Bancassurance and a corporate agency tie-up with at least 2 Scheduled Commercial Banks, preferably 1 Public Sector Bank; certificate from beneficiary bank required.",
      "pages": [
        10
      ]
    },
    {
      "text": "Must have a minimum Claim Settlement Ratio of 90% in the last 2 financial years as on 31.03.2025 (FY24-25 and FY23-24).",
      "pages": [
        10
      ]
    },
    {
      "text": "Must have a minimum Solvency Ratio of 150% as on 31.03.2025 (C.A. certificate basis).",
      "pages": [
        10
      ]
    },
    {
      "text": "Must have minimum average Rs.5000 Crores underwritten premium (new business plus renewal) in the last 2 years.",
      "pages": [
        10
      ]
    },
    {
      "text": "Must sign the Integrity Pact (Annexure-17), a preliminary qualification; in a joint venture all partners must sign.",
      "pages": [
        19,
        49
      ]
    },
    {
      "text": "Must confirm in Annexure 15 that it is not blacklisted by any tie-up partner, PSU, PSB or private bank, has no pending cheating/fraud case, and has no IRDAI or other regulatory penalty or warning (details to be given if any).",
      "pages": [
        39
      ]
    }
  ]
}

{
  "important_dates": [
    {
      "text": "Tender publishing date: 11.05.2026.",
      "pages": [
        4
      ]
    },
    {
      "text": "Last date for seeking clarification: 18.05.2026 (by 5.00 PM, by email to mdd@iob.bank.in).",
      "pages": [
        4,
        12
      ]
    },
    {
      "text": "Issue of clarifications: 27.05.2026.",
      "pages": [
        4
      ]
    },
    {
      "text": "Last date and time for receipt of proposals: 08.06.2026 up to 5.00 PM; no proposal is accepted after this.",
      "pages": [
        4,
        13
      ]
    },
    {
      "text": "Opening of proposals: 10.06.2026, 11.00 AM.",
      "pages": [
        4
      ]
    },
    {
      "text": "Technical evaluation by the department: 12.06.2026.",
      "pages": [
        4
      ]
    },
    {
      "text": "Presentation by shortlisted bidders: 17.06.2026.",
      "pages": [
        4
      ]
    },
    {
      "text": "Proposal validity: 180 days from the last date of submission.",
      "pages": [
        13
      ]
    }
  ]
}

{
  "commercial_requirements": [
    {
      "text": "Successful bidder pays the Bank remuneration/commission on each policy issued at mutually decided rates, within IRDAI regulations, on a monthly basis.",
      "pages": [
        8
      ]
    },
    {
      "text": "Commission must be remitted to the Bank by the 10th working day of every month with details of all policies issued till the end of the previous month.",
      "pages": [
        8
      ]
    },
    {
      "text": "Bank reserves the right to negotiate pricing/commission with the L1 insurance company anytime during the tenure of the agreement.",
      "pages": [
        21
      ]
    },
    {
      "text": "Bank may impose penalties and Liquidated Damages if performance is not as per its satisfaction; rate or cap not specified in the document.",
      "pages": [
        20
      ]
    },
    {
      "text": "Bank may set off any amount due to the Company and is not liable to pay damages to the Company in any condition.",
      "pages": [
        20
      ]
    },
    {
      "text": "Bidder bears all bid preparation costs and the cost of registration on the e-tendering portal.",
      "pages": [
        11,
        14
      ]
    }
  ]
}

{
  "commercial_requirements": [
    {
      "text": "Annexure-4 asks for maximum commission approved by IRDAI and maximum offered to the Bank per product; all commission must comply with IRDAI (Expenses of Management, including Commission, of Insurers) Regulations, 2024 (effective 01.04.2024).",
      "pages": [
        28
      ]
    },
    {
      "text": "EMD/bid security and Performance Bank Guarantee are mentioned in the Integrity Pact but no amount is stated anywhere; tender fee and warranty are not specified in the document.",
      "pages": [
        50
      ]
    }
  ]
}

{
  "project_duration": [
    {
      "text": "Tie-up is initially for a period of 3 years, subject to satisfactory performance and annual review; the Bank may renew for a further 3 years or discontinue.",
      "pages": [
        7
      ]
    },
    {
      "text": "Business sourcing from all centres is permitted for the initial 01 year, then 2 years more on satisfactory performance, subject to annual review.",
      "pages": [
        8
      ]
    },
    {
      "text": "Tie-up commencement date is to be determined or advised after the selection process is complete.",
      "pages": [
        17
      ]
    },
    {
      "text": "Integrity Pact is valid for 5 years or until complete execution of the contract including warranty, whichever is later; if the bidder is unsuccessful it expires six months after contract signing.",
      "pages": [
        52
      ]
    }
  ]
}

{
  "important_conditions": [
    {
      "text": "Submission: only via the e-tendering portal https://iobtenders.auctiontiger.net; the portal accepts no bids after the deadline and the acknowledgement must be kept.",
      "pages": [
        4,
        11
      ]
    },
    {
      "text": "Submission: data must be in the formats of Annexure 1 to Annexure 20, in English, in Indian Rupees, for the financial year ending March 31, 2025; other formats make the proposal non-compliant.",
      "pages": [
        14,
        15
      ]
    },
    {
      "text": "Submission: every page of the RFP document must be signed by the authorised person; bids with unsigned documents will be summarily rejected.",
      "pages": [
        5
      ]
    },
    {
      "text": "Submission: no overwriting, erasures or handwritten corrections; replies such as OK, accepted or noted are not acceptable.",
      "pages": [
        14
      ]
    },
    {
      "text": "Submission: verify the Class III Digital Certificate with the service provider at least two days before the due date; a mock drill is advised.",
      "pages": [
        11
      ]
    },
    {
      "text": "Risk: submission mode conflicts. The schedule and bid process allow submission only through the e-tendering portal, but one preface bullet says the bid in physical form with supporting documents should be submitted by the due date.",
      "pages": [
        4,
        5,
        11
      ]
    }
  ]
}

{
  "important_conditions": [
    {
      "text": "Evaluation: three stages - minimum eligibility (any failure rejects the proposal), technical evaluation carrying 70 marks, and a presentation carrying 30 marks.",
      "pages": [
        15,
        17
      ]
    },
    {
      "text": "Evaluation: technical scoring covers 14 parameters, maximum 70 marks in total, including solvency ratio, profit after tax, claim settlement ratio, Gross Written Premium, bank tie-ups, branches and penalties.",
      "pages": [
        15,
        16
      ]
    },
    {
      "text": "Evaluation: top shortlisted bidders on technical score are invited to present; the Bank decides the cut-off marks and the number of bidders; bidders bear their own travel and stay costs.",
      "pages": [
        17
      ]
    },
    {
      "text": "Risk: penalties and Liquidated Damages can be imposed at the Bank's satisfaction with no rate or cap stated; the Bank is not liable to pay damages to the Company.",
      "pages": [
        20
      ]
    },
    {
      "text": "Risk: the Bank may terminate by notice without assigning reason and the Company cannot terminate for convenience, while another clause says either party may terminate the tie-up per IRDAI Regulations.",
      "pages": [
        17,
        20
      ]
    },
    {
      "text": "Risk: how the 70 technical and 30 presentation marks combine into a final rank is not stated, yet award goes to the L1 bidder with commission negotiable afterwards.",
      "pages": [
        15,
        17,
        21
      ]
    }
  ]
}

{
  "important_conditions": [
    {
      "text": "Risk: indemnity is uncapped, covering all actions, claims, losses and advocates' fees from repudiation or delay in settlement of claims or any matter connected with the agreement.",
      "pages": [
        23
      ]
    },
    {
      "text": "Risk: suspected data breaches must be notified within 4 hours, and the provider bears financial losses or penalties up to an 'agreed Cap' that the document does not define.",
      "pages": [
        44
      ]
    }
  ]
}

{
  "overview": {
    "text": "Life Insurance Corporation of India (LIC), Central Office, Mumbai, invites online two-bid tenders for procurement and implementation of tools for the DPDP Act, 2023 and DPDP Rules, 2025, covering 12 modules such as consent management, data discovery and breach management, for a period of five (5) years. Ref: LIC-CO/ERM/CSD/RFP/2026-27/DPDPA_Tools Dated: 13/07/2026.",
    "pages": [
      1,
      9,
      11
    ]
  }
}

{
  "issuing_organization": "Life Insurance Corporation of India (LIC); Central Office, ERM/CSD (Cyber Security) Department, Mumbai; Ref: LIC-CO/ERM/CSD/RFP/2026-27/DPDPA_Tools Dated: 13/07/2026; contact: dpdpbid@licindia.com",
  "issuing_organization_pages": [
    1,
    10
  ]
}

{
  "scope": [
    {
      "text": "Supply, implement and support a DPDP compliance solution of 12 modules: Data Privacy Notice Management, Consent Management Platform, Cookie Consent Management, Data Discovery & Mapping, Data Principal Rights Management (including Grievance Redressal), DPIA, ROPA, Personal Data Breach Management, Third Party Vendor Risk Management, Compliance Reporting & Dashboards, Workflow Management and a DPDP Program Management portal. List is not exhaustive.",
      "pages": [
        11,
        27
      ]
    },
    {
      "text": "Six phases with deliverables for each module: Planning & Designing workshop, Implementation, User acceptance testing, Movement to production, Training and knowledge transfer, and Post implementation support. The activity list is indicative, not exhaustive.",
      "pages": [
        27
      ]
    }
  ]
}

{
  "scope": [
    {
      "text": "Supply and install software and hardware (if any) for DC and DR in HA mode, deployed in pre-production, production and DR environments, with all licences registered in LIC's name.",
      "pages": [
        28,
        35
      ]
    },
    {
      "text": "Bidder must engage OEMs for plan, design and implementation; the OEM holds overall implementation responsibility, certifies the architecture and audits deployment at the end of implementation and once every year during the contract period.",
      "pages": [
        28,
        29,
        33
      ]
    }
  ]
}

{
  "scope": [
    {
      "text": "Integrate with LIC applications and systems including SIEM, PAM, Active Directory/LDAP, SMS and email gateways and a centralized identity repository; the solution should work with SOAR for incident handling.",
      "pages": [
        28,
        35,
        38
      ]
    }
  ]
}

{
  "scope": [
    {
      "text": "Training at LIC premises in Mumbai: hands-on training before and after implementation, certification-level training for three participants at no additional cost, and training twice every year for each module till end of contract.",
      "pages": [
        31,
        36
      ]
    }
  ]
}

{
  "scope": [
    {
      "text": "After go-live, manage and monitor the solution end to end for the five-year term, with level-1, level-2 and level-3 support, root cause analysis, VAPT remediation, DR drill support and a 24/7/365 support contact centre.",
      "pages": [
        35,
        37
      ]
    }
  ]
}

{
  "scope": [
    {
      "text": "Deploy a total of 24 dedicated onsite resources for the contract duration, including an onsite Project Manager, on LIC premises in Mumbai.",
      "pages": [
        43,
        44,
        45
      ]
    }
  ]
}

{
  "key_requirements": [
    {
      "text": "Bidder must comply with every parameter of Annexure XV technical specifications (separate Excel); non-compliance to any parameter means the bid is not evaluated. The specifications are minimum, equivalent or higher may be quoted.",
      "pages": [
        13,
        33
      ]
    },
    {
      "text": "The solution must accommodate a yearly project growth rate of up to 10%, with licence prices and a breakdown of charges for additional licences quoted upfront.",
      "pages": [
        34
      ]
    },
    {
      "text": "A detailed execution plan with designs must be submitted to LIC within 5 weeks of placing the order; execution starts only after LIC approves it.",
      "pages": [
        34
      ]
    },
    {
      "text": "Desirable: log storage of at least 12 months, and 2 years in the SIEM, with logs retrievable within 5 hours of any breach.",
      "pages": [
        34
      ]
    }
  ]
}

{
  "key_requirements": [
    {
      "text": "The complete solution must be deployed on-premises only at LIC; no component may be deployed outside the LIC network at any time.",
      "pages": [
        38
      ]
    },
    {
      "text": "The solution must not go live until all VAPT observations are resolved and LIC's delegated committee approves; bidder is solely responsible for closing the findings.",
      "pages": [
        38
      ]
    },
    {
      "text": "The bidder needs to provide hardware, support and licences for 5 years post Go-live for all modules; all licences must be in the name of Life Insurance Corporation of India.",
      "pages": [
        38
      ]
    },
    {
      "text": "Software and accessories must be IPv6 compatible and prepared for TLS 1.3 or higher; encryption of data in transit and at rest is desirable.",
      "pages": [
        35,
        38
      ]
    },
    {
      "text": "Desirable: RTO of 4 hours and RPO of 15 minutes; DC and DR in active-passive mode for all infrastructure.",
      "pages": [
        38,
        41
      ]
    }
  ]
}

{
  "key_requirements": [
    {
      "text": "All onsite personnel must be full-time employees on the vendor's payroll; outsourced or subcontracted personnel are not permitted. Police background verification is required.",
      "pages": [
        45
      ]
    }
  ]
}

{
  "eligibility": [
    {
      "text": "Bidder must be a system integrator and a registered legal entity in India in operation for a minimum of 5 years preceding the RFP date, with valid GST registration and PAN card.",
      "pages": [
        11
      ]
    },
    {
      "text": "Bidder must have average annual turnover of not less than INR 100 Crores over the last three audited financial years (FY2023-2024, FY2024-2025, FY2025-2026), operating profit (EBITDA) in those years and positive net worth as on RFP date; CA certificate without riders.",
      "pages": [
        11
      ]
    },
    {
      "text": "Bidder or OEM must have implemented, or be implementing, privacy automation solutions with at least consent management, data principal rights management and data discovery for at least two (2) organizations in the insurance and/or banking sectors.",
      "pages": [
        11,
        12
      ]
    },
    {
      "text": "Bidder must have revenue of at least 50 Crore from DPDP related projects and Services / Cyber Security Projects in each of the last 3 financial years (FY 2023-24, FY 2024-25, FY 2025-26). Bidder and OEM must have a support center in Mumbai with 24x7 onsite, telephonic and remote support.",
      "pages": [
        12
      ]
    },
    {
      "text": "Bidder must have a minimum of 30 permanent Data Privacy / IT Security professionals on payroll with certifications such as CIPT, CIPP/E, CIPM, DSCI, CISSP, OSCP, CEH, CISA or CISM, and must hold any 3 of ISO27001, ISO9001, ISO22301, ISO 20000.",
      "pages": [
        12
      ]
    },
    {
      "text": "OEM must have average annual turnover of not less than INR 500 Crores over the last three audited financial years, with positive EBITDA, PAT and Net Worth in each; its product must be commercially available for a minimum of two years and implemented or under implementation at at least three enterprise customers.",
      "pages": [
        12
      ]
    },
    {
      "text": "OEM must have a dedicated implementation team (Project Manager, Solution Architect, Privacy Consultant, Technical Specialists) with minimum five years' experience. Bidder or OEM must have an in-house privacy legal team or a signed MoU with law firms or privacy consultancies, with at least two CVs of legal experts (LLB/LLM).",
      "pages": [
        12,
        13
      ]
    }
  ]
}

{
  "eligibility": [
    {
      "text": "Bidder must not be blacklisted by Government of India, RBI, SEBI or IRDAI (void if a court stay order is obtained), and must give a duplicate-participation undertaking, a signed Integrity Pact, Manufacturer Authorization Form and Land Border declaration. Consortium bids are rejected.",
      "pages": [
        12,
        13,
        16
      ]
    }
  ]
}

{
  "important_dates": [
    {
      "text": "RFP issuance date: 13/07/2026.",
      "pages": [
        9
      ]
    },
    {
      "text": "Pre-bid queries and participant details due 20-07-2026, latest by 03.00 PM, by email to dpdpbid@licindia.com.",
      "pages": [
        9
      ]
    },
    {
      "text": "Pre-bid meeting on 22-07-2026, 11:00 am to 1:30 pm, at LIC Central Office, Cyber Security Department, Mumbai; maximum 2 representatives per bidder.",
      "pages": [
        9
      ]
    },
    {
      "text": "Last date and time for bid submission: 10-08-2026, latest by 03:00 PM.",
      "pages": [
        10
      ]
    },
    {
      "text": "Eligibility bid opening: 10-08-2026, 03:15 PM.",
      "pages": [
        10
      ]
    },
    {
      "text": "Commercial bid opening date, time and venue: to be intimated to eligible qualified bidders later.",
      "pages": [
        10
      ]
    },
    {
      "text": "The schedule is tentative and subject to change; changes are notified through the LIC website.",
      "pages": [
        10
      ]
    }
  ]
}

{
  "important_dates": [
    {
      "text": "Hard copies of the bid in sealed envelopes are due within three working days of eligibility bid opening.",
      "pages": [
        16
      ]
    },
    {
      "text": "Bid validity: 1 year from the last date of bid submission.",
      "pages": [
        18
      ]
    }
  ]
}

{
  "commercial_requirements": [
    {
      "text": "Bid processing fee: non-refundable Rs.11,800/- inclusive of GST (10000+18%GST), paid online. Micro and Small Enterprises are exempt with an MSME/NSIC certificate. A bid without the fee or valid exemption documents is rejected.",
      "pages": [
        10,
        14
      ]
    },
    {
      "text": "EMD: INR 83,00,000 (Rupees Eighty-Three Lakhs Only) as an unconditional and irrevocable Bank Guarantee payable at Mumbai, valid for one year from the last date of submission; non-submission disqualifies. MSEs with MSME/NSIC certificate are exempt. Unsuccessful bidders get a refund within 45 days of the result.",
      "pages": [
        10,
        15
      ]
    }
  ]
}

{
  "commercial_requirements": [
    {
      "text": "Performance Bank Guarantee: unconditional and irrevocable, 5% of total Contract Value, due within 15 days of the selection letter and valid for 63 months. Delay costs Rs.5,000/- per day up to Rs.1,00,000/-; after 35 days LIC may cancel and award to the L2 bidder at L1 prices.",
      "pages": [
        21
      ]
    },
    {
      "text": "Comprehensive on-site warranty of five (5) years from installation and acceptance, including updates and patches at no extra cost; spares and support must be available for a minimum of six years from installation.",
      "pages": [
        33,
        47
      ]
    }
  ]
}

{
  "commercial_requirements": [
    {
      "text": "No advance payment; paid in INR by NEFT after deductions. Milestones per solution: 40 % on delivery of all software/appliances and contract signing; 40 % on installation, integration, initial OEM audit and acceptance testing, plus 100% of Direct Premium Support Cost with OEMs; 15 % after go-live and OEM validation; 5 % on training and documentation. Onsite services are paid quarterly in arrear subject to SLA.",
      "pages": [
        46,
        48
      ]
    },
    {
      "text": "Delay penalties: 0.25 % of the total PO value of the hardware per week of delay or part thereof, same rate on delayed software/appliances value; HLD and LLD beyond 6 weeks of PO, 0.02% of the total PO value per week; onsite person leaving before 1 year, 2 % of annual on-site charges plus 1% per repeat.",
      "pages": [
        50,
        51
      ]
    }
  ]
}

{
  "commercial_requirements": [
    {
      "text": "SLA breach penalties are capped cumulatively at 10% of the contract value (TCO); delivery and installation penalties at 10% of the PO value; onsite and offsite support penalties at 100% of quarterly charges.",
      "pages": [
        50,
        52
      ]
    }
  ]
}

{
  "project_duration": [
    {
      "text": "The bidder shall complete the entire activity within 20 weeks of signing of contract.",
      "pages": [
        40
      ]
    },
    {
      "text": "Post Go-Live support runs 5 years from Go-live date.",
      "pages": [
        40
      ]
    },
    {
